head.script:
// https://inswave01.atlassian.net/browse/WAEA-879



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > checkEditableInputClass]<br/>Body Cell 이 inputType='text' 이고 readonly 또는 disabled 상태일 때 'w2grid_input' 클래스를 제거할지 설정합니다.",
    "validation" : [
        "true 설정 시 inputType='text' 이고 readonly 또는 disabled 상태인 Body Cell 의 nobr 태그에 'w2grid_input' CSS 클래스를 설정하지 않습니다.",
        "false(기본값) 설정 시 inputType='text' 이고 readonly 또는 disabled 상태인 Body Cell 의 nobr 태그에 항상 'w2grid_input' CSS 클래스를 설정합니다.",
        "Body Cell 이 readonly 또는 disabled 상태이면 'w2grid_input_readonly' 또는 'w2grid_input_disabled' CSS 클래스가 nobr 태그에 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 — boolean 옵션은 gdl_boolean + getText() 패턴
    let conVal = con_checkEditableInputClass.getText();

    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
        readOnly: true,
    };
    // 미설정("") 일 때는 속성 자체를 제외
    if (conVal !== "") {
        properties.checkEditableInputClass = conVal;
    }

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (2 row x 2 col)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 2);

    // target 생성
    $c.gcm.createBasicGridView(cList);

    // 동일한 disabled 적용
    // target1.setCellDisabled(0, "col1", true);
    // target1.setCellReadOnly(0, "col2", true);
    target1.setDisabled('grid', true);
}



scwin.btn_getCellClassName_onclick = function () {
    var cols = ["col1", "col2"];
    for (var r = 0; r < 2; r++) {
        for (var c = 0; c < cols.length; c++) {
            var td = document.querySelector("[id*='target1_cell_" + r + "_" + c + "']");
            var nobr = td ? td.firstElementChild : null;
            var cn = nobr ? nobr.className : "(nobr 없음)";
            wf_body_bottom.getObj("scwin").setReturnValue("cell(" + r + "," + cols[c] + ") nobr.className : " + cn);
        }
    }
}
